content.solution_code:
class Spacecraft {
  constructor(name) {
    this.name = name;
  }

  launch() {
    return `${this.name} is launching into orbit!`;
  }
}

class CargoShip extends Spacecraft {
  #currentCargo;

  constructor(name, cargoCapacity) {
    super(name);
    this.cargoCapacity = cargoCapacity;
    this.#currentCargo = 0;
  }

  loadCargo(amount) {
    this.#currentCargo = Math.min(this.#currentCargo + amount, this.cargoCapacity);
  }

  unloadCargo(amount) {
    this.#currentCargo = Math.max(this.#currentCargo - amount, 0);
  }

  getCurrentCargo() {
    return this.#currentCargo;
  }

  launch() {
    return `${this.name} is launching with ${this.#currentCargo} tons of cargo!`;
  }
}

